def require(ok, code):
    if not ok:
        raise RuntimeError(code)


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def pin(raw):
    return {'bytes': len(raw), 'sha256': sha(raw)}


def pairs(items):
    value = {}
    for key, item in items:
        require(key not in value, 'DUPLICATE_JSON_KEY')
        value[key] = item
    return value


def decode(raw):
    return json.loads(raw, object_pairs_hook=pairs)


def ordinary(path, directory=False):
    require(path.is_absolute() and '..' not in path.parts, 'EXACT_ABSOLUTE_PUBLIC_PATH')
    for node in [*reversed(path.parents), path]:
        item = node.lstat()
        require(not stat.S_ISLNK(item.st_mode) and not (getattr(item, 'st_file_attributes', 0) & 1024), 'NO_SYMLINK_REPARSE')
        require(stat.S_ISDIR(item.st_mode) if node != path or directory else stat.S_ISREG(item.st_mode), 'ORDINARY_PUBLIC_NODE')


def stamp(path):
    row = path.lstat()
    return [getattr(row, key) for key in ['st_dev', 'st_ino', 'st_mode', 'st_nlink', 'st_uid', 'st_gid', 'st_size', 'st_mtime_ns', 'st_ctime_ns']]


def read(path):
    ordinary(path)
    before = stamp(path)
    raw = path.read_bytes()
    require(stamp(path) == before and len(raw) == before[6], 'COMPLETE_STABLE_PUBLIC_READ')
    return raw


def descriptor(path, raw):
    return {'path': path.as_posix(), **pin(raw)}


def pinned(path, expected):
    raw = read(path)
    require(pin(raw) == expected, 'FIXED_ORIGINAL_PUBLIC_PIN')
    return raw


def tree(root):
    ordinary(root, True)
    rows, directories = [], []
    def on_error(error):
        raise error
    for current, children, leaves in os.walk(root, followlinks=False, onerror=on_error):
        current = Path(current); ordinary(current, True)
        directories.append({'path': current.as_posix(), 'stat9': stamp(current)})
        for name in children:
            ordinary(current / name, True)
        for name in leaves:
            path = current / name; raw = read(path)
            rows.append(descriptor(path, raw) | {'stat9': stamp(path)})
    return {'files': sorted(rows, key=lambda row: row['path']),
        'directories': sorted(directories, key=lambda row: row['path'])}


def save(path, raw):
    require(path.parent == OUT and path.name not in ['', '.', '..'], 'WRITE_ONLY_THIS_NEW_FLAT_OUTPUT')
    with path.open('xb') as stream:
        require(stream.write(raw) == len(raw), 'FULL_EXCLUSIVE_WRITE')
        stream.flush(); os.fsync(stream.fileno())
    require(read(path) == raw, 'FULL_EXCLUSIVE_WRITE_READBACK')


def save_json(name, value):
    raw = (json.dumps(value, ensure_ascii=False, indent=2) + '\n').encode('utf-8')
    save(OUT / name, raw)
    return descriptor(OUT / name, raw)


def same_facts(before, after):
    require(set(before) == set(after) and {key: value for key, value in before.items() if key != 'mounts'}
        == {key: value for key, value in after.items() if key != 'mounts'}, 'FULL_NATIVE_STATE_FIELDS_UNCHANGED')
    canonical = lambda rows: sorted(json.dumps(row, sort_keys=True, separators=(',', ':')) for row in rows)
    require(canonical(before['mounts']) == canonical(after['mounts']), 'FULL_NATIVE_MOUNT_ENTRY_MULTISET_UNCHANGED')


def terminal(facts, exit_code):
    require(facts['status'] == 'exited' and type(facts['pid']) is int and facts['pid'] == 0
        and type(facts['restart_count']) is int and facts['restart_count'] == 0
        and type(facts['exit_code']) is int and facts['exit_code'] == exit_code, 'EXACT_ORIGINAL_TERMINAL_STATE')


def native(label, arguments, executable=DOCKER):
    index = len(OPERATIONS) + 1
    stem = '%03d-' % index + re.sub('[^a-z0-9-]', '-', label.lower())
    argv = [executable, *arguments]
    process = subprocess.Popen(argv, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    save_json(stem + '.created.json', {'argv': argv, 'pid': process.pid})
    stdout, stderr = process.communicate()
    waited = process.wait()
    save(OUT / (stem + '.stdout'), stdout)
    save(OUT / (stem + '.stderr'), stderr)
    row = {'index': index, 'label': label, 'stem': stem, 'argv': argv, 'pid': process.pid,
        'native_exit': process.returncode, 'wait_returncode': waited,
        'stdout_bytes': len(stdout), 'stdout_sha256': sha(stdout),
        'stderr_bytes': len(stderr), 'stderr_sha256': sha(stderr)}
    save_json(stem + '.terminal.json', row)
    OPERATIONS.append(row)
    require(type(process.pid) is int and process.pid > 0 and type(process.returncode) is int
        and type(waited) is int and process.returncode == waited == 0 and stderr == b'',
        'ACTUAL_SAME_NATIVE_PID_WAIT_ZERO_EMPTY_STDERR')
    return stdout


def created_never_started(facts):
    require(facts['status'] == 'created' and facts['pid'] == facts['restart_count'] == facts['exit_code'] == 0
        and all(type(facts[key]) is int for key in ['pid', 'restart_count', 'exit_code'])
        and facts['started_at'] == facts['finished_at'] == '0001-01-01T00:00:00Z',
        'ORIGINAL_PAID_CREATED_NEVER_STARTED')


def native_original(stem, pid, code):
    created = decode(read(Path(str(stem) + '.created.json')))
    ended = decode(read(Path(str(stem) + '.terminal.json')))
    require(created['pid'] == ended['pid'] == pid and ended['native_exit'] == ended['wait_returncode'] == code,
        'SAME_ORIGINAL_NATIVE_CREATED_TERMINAL_PID_ACTUAL_EXIT')
    for stream in ['stdout', 'stderr']:
        raw = read(Path(str(stem) + '.' + stream))
        item = ended.get(stream)
        expected = ({key: item[key] for key in ['bytes', 'sha256']} if type(item) is dict
            else {'bytes': ended[stream + '_bytes'], 'sha256': ended[stream + '_sha256']})
        require(pin(raw) == expected and (stream != 'stderr' or raw == b''), 'FULL_ORIGINAL_NATIVE_RAW_STREAM')
    return ended


def failure_inputs():
    for name, expected in AUTHOR_PINS.items():
        pinned(Path(name), expected)
    context = decode(read(RUN / 'actual-run-context.json'))
