def public_snapshot(context, frozen):
    records, directories = {}, {}
    def merge(snapshot):
        for field, target in [('files', records), ('directories', directories)]:
            for row in snapshot[field]:
                require(row['path'] not in target or target[row['path']] == row, 'OVERLAPPING_PUBLIC_NATIVE_PINS_IDENTICAL')
                target[row['path']] = row
    for folder in [RUN, NORMAL_ROOT, MATERIALIZER, LAUNCHER, ROOT, READBACK, DIAGNOSTIC, PREDECESSOR_SOURCE, PREDECESSOR_AUTHOR]:
        merge(tree(folder))
    require(set(os.listdir(ROOT)) == set(SOURCE_NAMES), 'EXACT_FIVE_SOURCE_FILES')
    artifacts = frozen['artifact_files']
    require(len(artifacts) == 9 and set(os.listdir(PROFILE)) == {row['path'] for row in artifacts}, 'EXACT_FROZEN_NINE_PROFILE_NAMESPACE')
    for expected in artifacts:
        pinned(PROFILE / expected['path'], {'bytes': expected['bytes'], 'sha256': expected['sha256']})
    receipt = decode(read(NORMAL_ROOT / 'materialize-freeze-assets-r1/RESULT.json'))
    require(receipt['source_sha'] == SOURCE and receipt['freeze_sha256'] == FREEZE
        and receipt['status'] == 'ACTUAL_CLEAN_SOURCE_AND_NINE_FILE_PROFILE_FROZEN_ONLY'
        and receipt['unique_source_files_actual_read'] == 10886
        and receipt['source_counts'] == {'driver':10,'customer':10865,'paid':10866,'fulfillment':10881,'aftersale_review':10885,'worker':10886}
        and len(receipt['native_operations']) == 277, 'ACTUAL_M277_AND_COMPLETE10886_SOURCE_UNION')
    for operation in receipt['native_operations']:
        require(type(operation['pid']) is int and operation['pid'] > 0
            and type(operation['native_exit']) is int and type(operation['wait_returncode']) is int
            and operation['native_exit'] == operation['wait_returncode'] == 0
            and operation['stderr_bytes'] == 0 and operation['stderr_sha256'] == sha(b''), 'ACTUAL_M277_ALL_NATIVE_WAIT_ZERO')
    for key, count in [('root_source_snapshot', 14), ('complete_source_snapshot', 31008)]:
        item = receipt[key]
        mapping = decode(pinned(Path(item['path']), {field: item[field] for field in ['bytes', 'sha256']}))
        require(type(mapping) is dict and len(mapping) == count, 'ACTUAL_M_COMPLETE_SOURCE_MAPPING_COUNT')
        for name, expected in mapping.items():
            require(set(expected) == {'path', 'bytes', 'sha256', 'stat9'} and expected['path'] == name
                and type(expected['stat9']) is list and len(expected['stat9']) == 9
                and all(type(value) is int for value in expected['stat9']), 'EXACT_M_NATIVE_NINE_SCHEMA')
            path = Path(name)
            require(key != 'complete_source_snapshot' or any(path.is_relative_to(root) for root in source_repos()),
                'M_SOURCE_ONLY_ORIGINAL_DEV_VAL')
            actual = descriptor(path, read(path)) | {'stat9': stamp(path)}
            require(actual == expected, 'COMPLETE_ORIGINAL_M_SOURCE_BYTES_NATIVE_NINE_HELD')
            merge({'files': [actual], 'directories': []})
        if key == 'complete_source_snapshot':
            expected_sources = set(mapping)
            complete_mapping = mapping
    union = {}
    for prefix, count in receipt['source_counts'].items():
        members = frozen[prefix + '_source_files']
        require(len(members) == count and len({row['path'] for row in members}) == count, 'COMPLETE_FROZEN_SOURCE_GROUP_MEMBERS')
        for row in members:
            require(set(row) == {'path','bytes','sha256'} and (row['path'] not in union or union[row['path']] == row), 'SOURCE_UNION_OVERLAPS_IDENTICAL')
            union[row['path']] = row
    require(len(union) == 10886, 'EXACT_COMPLETE10886_FROZEN_SOURCE_UNION')
    for relative, row in union.items():
        for repo in source_repos():
            actual = complete_mapping[(repo / relative).as_posix()]
            require({key: actual[key] for key in ['bytes','sha256']} == {key: row[key] for key in ['bytes','sha256']}, 'FROZEN_SOURCE_UNION_JOINS_COMPLETE_TWO_TREE_BYTES')
    roots = ['crmeb/app', 'crmeb/crmeb', 'crmeb/vendor', 'crmeb/config', 'help/migrations',
        'help/audit-regressions/isolated', 'template/admin/src', 'template/merchant', 'template/uni-app']
    for repo in source_repos():
        for relative in roots:
            folder = repo / relative
            snapshot = tree(folder)
            require({row['path'] for row in snapshot['files']}
                == {name for name in expected_sources if Path(name).is_relative_to(folder)},
                'ORIGINAL_SOURCE_DIRECTORY_NAMESPACE_COMPLETE')
            merge(snapshot)
    require(len(receipt['materialize_source_inputs']) == 3, 'ORIGINAL_M_THREE_SOURCE_INPUTS')
    for name, expected in receipt['materialize_source_inputs'].items():
        path = Path(name)
        require(descriptor(path, read(path)) | {'stat9': stamp(path)} == expected,
            'ORIGINAL_M_SOURCE_FULL_BYTES_NATIVE_NINE')
    group = frozen['proof_php_ini']
    proof = context['proof_php_ini_copy']
    copy = decode(pinned(RUN / proof['path'], {key: proof[key] for key in ['bytes', 'sha256']}))
    require(all(copy[key] == context[key] for key in ['run_id', 'source_sha', 'freeze_sha256'])
        and proof['path'] == 'evidence/proof-php-ini-copy.json'
        and copy['copy']['path'] == (RUN / 'proof-php-ini/99-ms4-proof-memory.ini').as_posix(), 'ORIGINAL_PROOF_INI_COPY_BOUND')
    original = Path(group['source_root']) / '99-ms4-proof-memory.ini'
    require(group['scope'] == 'MS4_PROOF_PHP_INI_RESOURCE_SOURCE' and group['files'] == [{'path': '99-ms4-proof-memory.ini',
        'bytes': 18, 'sha256': '986c7e4b2587348a8d5ba59312a2106d38bbefec35acda4e7e5c14761cfe9ff1'}]
        and read(original) == read(RUN / 'proof-php-ini/99-ms4-proof-memory.ini') == b'memory_limit=512M\n',
        'ORIGINAL_AND_COPIED_INI_EXACT_EIGHTEEN_BYTES')
    ref = group['config_reference']
    pinned(Path(ref['path']), {key: ref[key] for key in ['bytes', 'sha256']})
    for path in [original, Path(ref['path'])]:
        merge({'files': [descriptor(path, read(path)) | {'stat9': stamp(path)}], 'directories': []})
    return {'files': [records[name] for name in sorted(records)],
        'directories': [directories[name] for name in sorted(directories)]}


def source_repos():
    return [RUN.parents[2] / 'worktrees/ms4-asset-consumers', RUN.parents[2] / 'worktrees/ms4-aftersale-normal-check']


def source_git():
    for repo in source_repos():
        args = ['-c', 'safe.directory=' + repo.as_posix(), '-C', repo.as_posix()]
        require(native('original-source-head', [*args, 'rev-parse', 'HEAD'], 'git') == (SOURCE + '\n').encode(),
            'ORIGINAL_DEV_VAL_HEAD_UNCHANGED')
        require(native('original-source-clean', [*args, 'status', '--porcelain=v1', '--untracked-files=all'], 'git') == b'',
            'ORIGINAL_DEV_VAL_CLEAN')


def global_inventory(context, allowed, history):
    all_ids = native('global-cids-before', ['ps', '-aq', '--no-trunc']).decode().splitlines()
    require(len(all_ids) == len(set(all_ids)) and all(re.fullmatch('[a-f0-9]{64}', cid) for cid in all_ids),
        'COMPLETE_GLOBAL_UNIQUE_FULL_IDS')
    targets = set(ROLES.values()) | {row['id'] for row in history.values()}
    require(not ((targets - set(allowed)) & set(all_ids)), 'NO_RETIRED_HISTORICAL_OR_REMOVED_ORIGINAL_CID')
    template = '{"id":{{json .Id}},"mounts":{{json .Mounts}},"network_mode":{{json .HostConfig.NetworkMode}},"networks":{{json .NetworkSettings.Networks}}}'
    lines = native('global-safe-consumer-facts', ['inspect', '--format', template, *all_ids]).splitlines() if all_ids else []
    seen, rows = set(), []
    volumes = {row['name'] for row in context['initial_volumes']}
    network_name = context['initial_network']['Name']
    for line in lines:
        row = decode(line)
        require(type(row) is dict and set(row) == {'id', 'mounts', 'network_mode', 'networks'}
            and row['id'] in all_ids and row['id'] not in seen and type(row['mounts']) is list
            and type(row['networks']) is dict and type(row['network_mode']) is str, 'GLOBAL_COMPLETE_SAFE_CONSUMER_FIELDS')
        seen.add(row['id'])
        mode = row['network_mode']
        consumes = bool({item.get('Name') for item in row['mounts']} & volumes
            or network_name in row['networks'] or NETWORK_ID in row['networks'] or mode in {network_name, NETWORK_ID}
            or any(item.get('NetworkID') == NETWORK_ID for item in row['networks'].values())
            or mode.startswith('container:') and mode[len('container:'):] in targets)
        require(not consumes or row['id'] in allowed, 'NO_FOREIGN_ORIGINAL_RESOURCE_CONSUMER')
        rows.append(row)
    final = native('global-cids-after', ['ps', '-aq', '--no-trunc']).decode().splitlines()
    require(seen == set(all_ids) and len(final) == len(set(final)) and set(final) == set(all_ids), 'GLOBAL_INVENTORY_STABLE_COMPLETE')
    return {'container_count': len(all_ids), 'facts': sorted(rows, key=lambda row: row['id'])}


def fresh_six(context):
    rows = []
    for kind, args in [('container', ['ps', '-aq', '--no-trunc']), ('network', ['network', 'ls', '-q']), ('volume', ['volume', 'ls', '-q'])]:
        for label, value in [('project', 'com.docker.compose.project=' + context['project']), ('run', 'tianli.audit.run=' + RUN_ID)]:
            require(native('fresh-' + kind + '-' + label, [*args, '--filter', 'label=' + value]) == b'', 'FRESH_RAW_STDOUT_STDERR_EMPTY')
            rows.append({'kind': kind, 'label': label, 'operation_index': OPERATIONS[-1]['index']})
    return rows


def source_guard(expected_hash):
    require(re.fullmatch('[a-f0-9]{64}', expected_hash) is not None
        and sha(read(Path(__file__))) == expected_hash, 'ROOT_REVIEWED_EXACT_SOURCE_SHA')
    ordinary(ROOT, True)
    require(set(os.listdir(ROOT)) == set(SOURCE_NAMES) and not OUT.exists(), 'EXACT_FIVE_SOURCE_FILES_AND_FRESH_OUTPUT')
    pins = decode(read(ROOT / 'PINS.json'))
    require(pins['run_id'] == RUN_ID and pins['source_sha'] == SOURCE and pins['freeze_sha256'] == FREEZE
        and set(pins['files']) == set(SOURCE_NAMES) - {'PINS.json'}, 'EXACT_SOURCE_PACKAGE_PINS')
    for name, expected in pins['files'].items():
        pinned(ROOT / name, expected)


def validate_close(expected_hash, context, histories):
    require(re.fullmatch('[a-f0-9]{64}', expected_hash) is not None, 'ROOT_REVIEWED_CLOSE_RESULT_SHA')
    result_raw = read(CLOSE_OUT / 'RESULT.json')
    require(sha(result_raw) == expected_hash, 'EXACT_ACTUAL_CLOSE_RESULT')
    result = decode(result_raw)
    expected = {cid: role for role, cid in ROLES.items()}
    require(result['schema'] == 1 and result['run_id'] == RUN_ID and result['source_sha'] == SOURCE
        and result['freeze_sha256'] == FREEZE and result['expected_containers'] == expected
        and result['scope'] == 'FULL_A_PAID_PRODUCER_FAILURE_NORMAL_CLOSE_ONLY'
        and result['status'] == 'VERIFIED_PAID_PRODUCER_FAILURE_NORMAL_CLOSE_ZERO_RESIDUAL'
        and [result[key] for key in ['removed_containers', 'removed_internal_networks', 'removed_original_volumes']] == [3, 1, 8]
        and result['ordinary_stop_and_exact_nonforce_remove'] is True
        and result['all_original_public_bytes_stat9_namespaces_unchanged'] is True
        and result['failed_outer_pid'] == S_PID and result['failed_outer_native_exit'] == 1 and result['original_S_terminal'] == 'PRESENT'
        and result['original_completed_native_zero'] == 71 and result['MS5_driver_native_exit'] == 0
        and result['early_container_native_exit'] == 0 and result['early_receipt_published'] is True
        and result['early_command_counts'] == EARLY_COUNTS and result['files_bootstrap_native_exit'] == 0
        and result['customer_prepare_native_exit'] == 0 and result['paid_producer_native_exit'] == 1
        and result['paid_failure_code'] == 'M4C_PAID_UNCLASSIFIED_SOURCE_FAILURE' and result['paid_failure_phase'] == 'UNKNOWN'
        and result['first_throwable_location'] == 'UNKNOWN' and result['http_calls_completed'] == result['HTTP_child'] == 'UNKNOWN'
        and result['paid_result_public_file'] == 'ABSENT_NOT_A_PHASE_PROOF' and result['initializer_native_exit'] == 0
        and result['later_Task6_AR_Worker'] == 'NOT STARTED' and result['full_acceptance'] == 'INCOMPLETE'
        and result['business_guard'] == 'ORIGINAL_FAILURE_UNCHANGED_NOT_REINVOKED',
        'ACTUAL_CLOSE_SCOPE_AND_FAILURE_TRUTH')
    def artifact(key, name):
        row = result[key]
        path = CLOSE_OUT / name
        require(row['path'] == path.as_posix(), 'CLOSE_PUBLIC_ARTIFACT_EXACT_PATH')
        return pinned(path, {field: row[field] for field in ['bytes', 'sha256']})
    source_raw = artifact('source_copy', 'root-driver-source.py')
    require(source_raw == read(ROOT / 'normal-close.py')
        and result['source'] == descriptor(ROOT / 'normal-close.py', source_raw), 'EXACT_REVIEWED_CLOSE_SOURCE_AND_COPY')
    baseline = decode(artifact('public_input_pins', 'PUBLIC-INPUT-PINS.json'))
    states = decode(artifact('removable_states', 'three-original-removable-states.json'))
    require(set(states) == set(expected), 'EXACT_THREE_REMOVABLE_CIDS')
    for cid, role in expected.items():
        require(states[cid]['id'] == cid and states[cid]['labels']['tianli.audit.run'] == RUN_ID
            and states[cid]['labels']['com.docker.compose.project'] == context['project']
            and states[cid]['labels']['com.docker.compose.service'] == role, 'EXACT_REMOVABLE_BOUND_ROLE')
        terminal(states[cid], 1 if role == 'audit-ms5-paid-producer' else 0)
    same_facts(decode(read(RUN / 'evidence/paid-producer-terminal.json')),
        states[ROLES['audit-ms5-paid-producer']])
    after = decode(artifact('global_after', 'GLOBAL-AFTER.json'))
    require(after['container_count'] == len(after['facts']), 'CLOSE_COMPLETE_GLOBAL_FACTS_COUNT')
    required = {'root-driver-source.py', 'PUBLIC-INPUT-PINS.json', 'three-original-removable-states.json',
        'GLOBAL-BEFORE.json', 'GLOBAL-AFTER.json', 'RESULT.json'}
    expected_mutations = [
        ['stop', '--timeout', '-1', ROLES['audit-mysql']],
        ['stop', '--timeout', '-1', ROLES['audit-redis']],
        ['rm', *sorted(expected)], ['network', 'rm', NETWORK_ID],
        ['volume', 'rm', *sorted(row['name'] for row in context['initial_volumes'])]]
    mutations = []
    operations = result['operations']
    require(type(operations) is list and operations, 'ACTUAL_CLOSE_NATIVE_LEDGER_EXISTS')
    for index, operation in enumerate(operations, 1):
        stem = operation['stem']
        require(operation['index'] == index and re.fullmatch('[0-9]{3}-[a-z0-9-]+', stem) is not None
            and type(operation['pid']) is int and operation['pid'] > 0
            and type(operation['native_exit']) is int and type(operation['wait_returncode']) is int
            and operation['native_exit'] == operation['wait_returncode'] == 0, 'EACH_ACTUAL_CLOSE_NATIVE_PID_WAIT_ZERO')
        ended = decode(read(CLOSE_OUT / (stem + '.terminal.json')))
        created = decode(read(CLOSE_OUT / (stem + '.created.json')))
        require(ended == operation and created == {'argv': operation['argv'], 'pid': operation['pid']},
            'CLOSE_ACTUAL_CREATED_TERMINAL_JOIN')
        for stream in ['stdout', 'stderr']:
            raw = read(CLOSE_OUT / (stem + '.' + stream))
            require(pin(raw) == {'bytes': operation[stream + '_bytes'], 'sha256': operation[stream + '_sha256']}
                and (stream != 'stderr' or raw == b''), 'EACH_CLOSE_COMPLETE_RAW_NATIVE_STREAM')
        required.update(stem + suffix for suffix in ['.created.json', '.terminal.json', '.stdout', '.stderr'])
        argv = operation['argv']
        require(type(argv) is list and len(argv) >= 2 and all(type(value) is str for value in argv), 'COMPLETE_CLOSE_NATIVE_ARGV')
        if argv[0] == DOCKER:
            command = argv[1:]
            if command in expected_mutations:
                mutations.append(command)
            else:
                require(command[:1] in [['ps'], ['inspect']] or command[:2] in [
                    ['network', 'ls'], ['network', 'inspect'], ['volume', 'ls'], ['volume', 'inspect']],
                    'ONLY_EXACT_REMOVAL_OR_READ_ONLY_DOCKER_COMMANDS')
        else:
            require(argv[0] == 'git' and any(argv[1:] == ['-c', 'safe.directory=' + repo.as_posix(), '-C', repo.as_posix(), *suffix]
                for repo in source_repos() for suffix in [['rev-parse', 'HEAD'], ['status', '--porcelain=v1', '--untracked-files=all']]),
                'ONLY_ORIGINAL_SOURCE_READ_ONLY_GIT_COMMANDS')
    require(mutations == expected_mutations and set(os.listdir(CLOSE_OUT)) == required,
        'ONLY_ORDERED_TWO_NORMAL_STOPS_AND_THREE_EXACT_NONFORCE_REMOVALS_WITH_COMPLETE_LEDGER')
    expected_queries = [(kind, label) for kind in ['container', 'network', 'volume'] for label in ['project', 'run']]
    queries = result['fresh_queries']
    require([(row['kind'], row['label']) for row in queries] == expected_queries
        and len({row['operation_index'] for row in queries}) == 6, 'SIX_ACTUAL_CLOSE_FRESH_QUERY_RECORDS')
    command_by_kind = {'container': ['ps', '-aq', '--no-trunc'], 'network': ['network', 'ls', '-q'], 'volume': ['volume', 'ls', '-q']}
    for query in queries:
        row = operations[query['operation_index'] - 1]
        label = ('com.docker.compose.project=' + context['project'] if query['label'] == 'project' else 'tianli.audit.run=' + RUN_ID)
        require(row['argv'] == [DOCKER, *command_by_kind[query['kind']], '--filter', 'label=' + label]
            and row['stdout_bytes'] == row['stderr_bytes'] == 0
            and read(CLOSE_OUT / (row['stem'] + '.stdout')) == read(CLOSE_OUT / (row['stem'] + '.stderr')) == b'',
            'SIX_CLOSE_FRESH_QUERIES_BOTH_RAW_STREAMS_TRULY_EMPTY')
    return result, baseline


def main():
    global PHASE
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source-sha256', required=True)
    parser.add_argument('--close-result-sha256', required=True)
    args = parser.parse_args()
    source_guard(args.source_sha256)
    context, frozen, driver, driver_saved, histories = failure_inputs()
    result, baseline = validate_close(args.close_result_sha256, context, histories)
    PHASE = 'independent_complete_before_read'
    require(public_snapshot(context, frozen) == baseline, 'ORIGINAL_PUBLIC_SOURCE_INI_NATIVE_NINE_HELD_BEFORE_ZERO')
    close_before = tree(CLOSE_OUT)
    OUT.mkdir()
    save(OUT / 'root-driver-source.py', read(Path(__file__)))
    source_git()
    before = global_inventory(context, set(), histories)
    before_pin = save_json('GLOBAL-BEFORE.json', before)
    PHASE = 'six_fresh_independent_raw_empty_queries'
    queries = fresh_six(context)
    after = global_inventory(context, set(), histories)
    after_pin = save_json('GLOBAL-AFTER.json', after)
    source_git()
    PHASE = 'independent_complete_after_read'
    require(failure_inputs()[0] == context and public_snapshot(context, frozen) == baseline
        and tree(CLOSE_OUT) == close_before, 'ALL_ORIGINAL_AND_CLOSE_BYTES_NATIVE_NINE_NAMESPACES_UNCHANGED')
    output = {'schema': 1, 'scope': 'FULL_A_PAID_PRODUCER_FAILURE_INDEPENDENT_ZERO_ONLY',
        'status': 'VERIFIED_PAID_PRODUCER_FAILURE_INDEPENDENT_ZERO', 'run_id': RUN_ID,
        'source_sha': SOURCE, 'freeze_sha256': FREEZE, 'resource_mutations': 0,
        'Host_imported': False, 'close_imported_or_invoked': False, 'fresh_queries': queries,
        'global_before': before_pin, 'global_after': after_pin, 'close_result': descriptor(CLOSE_OUT / 'RESULT.json', read(CLOSE_OUT / 'RESULT.json')),
        'close_native_operations_verified': len(result['operations']), 'close_exact_mutating_operations_verified': 5,
        'all_original_and_close_public_bytes_stat9_namespaces_unchanged': True,
        'original_public_file_count': len(baseline['files']), 'original_source_mapping_records': 31008,
        'failed_outer_pid': S_PID, 'failed_outer_native_exit': 1, 'original_S_terminal': 'PRESENT',
        'original_completed_native_zero': 71, 'MS5_driver_native_exit': 0,
        'early_container_native_exit': 0, 'early_receipt_published': True, 'early_command_counts': EARLY_COUNTS,
        'files_bootstrap_native_exit': 0, 'customer_prepare_native_exit': 0, 'paid_producer_native_exit': 1,
        'paid_failure_code': 'M4C_PAID_UNCLASSIFIED_SOURCE_FAILURE', 'paid_failure_phase': 'UNKNOWN',
        'first_throwable_location': 'UNKNOWN', 'http_calls_completed': 'UNKNOWN', 'HTTP_child': 'UNKNOWN',
        'paid_result_public_file': 'ABSENT_NOT_A_PHASE_PROOF', 'initializer_native_exit': 0,
        'later_Task6_AR_Worker': 'NOT STARTED',
        'full_acceptance': 'INCOMPLETE', 'operations': OPERATIONS,
        'source': descriptor(Path(__file__), read(Path(__file__))),
        'source_copy': descriptor(OUT / 'root-driver-source.py', read(OUT / 'root-driver-source.py'))}
    save_json('RESULT.json', output)
    print(json.dumps({key: output[key] for key in ['status', 'run_id', 'resource_mutations',
        'failed_outer_native_exit', 'paid_producer_native_exit', 'full_acceptance']}), flush=True)


if __name__ == '__main__':
    try:
        main()
    except Exception as error:
        message = str(error)
        print(json.dumps({'status': 'FAILED_ZERO_STATE_PRESERVED_NO_RETRY_OR_AUTOMATIC_CLEANUP', 'phase': PHASE,
            'class': type(error).__name__, 'code': message if re.fullmatch('[A-Z0-9_]+', message) else None,
            'resource_mutations': 0}), flush=True)
        sys.exit(1)
